const item = $input.item.json;
return {
  json: {
    topic: item.Topic || item.topic || item.Title || 'AI Breakthroughs',
    category: (item.Category || item.category || 'tech').toLowerCase(),
    target_audience: item.Audience || 'General',
    source_url: item.Source || item.source_url || 'https://everygyan.com',
    sheet_row_number: item.row_number || item._rowNumber || null
  }
};

const topicData = $('Prepare Topic Context').item.json;
const articleData = $('Generate 500-Word Article...').item.json;
const rawImagePrompt = $input.item.json.text || topicData.topic || 'editorial infographic';

// Clean prompt and construct FLUX image URL
const cleaned = encodeURIComponent(
  rawImagePrompt.replace(/[\n\r]+/g, ' ').slice(0, 280) + ', editorial infographic, modern aesthetic, 8k'
);
const seed = Math.floor(Math.random() * 999999);
const imageUrl = `https://image.pollinations.ai/prompt/${cleaned}?width=1280&height=720&model=flux&nologo=true&seed=${seed}`;

return {
  json: {
    topic: topicData.topic,
    category: topicData.category,
    source_url: topicData.source_url,
    article_text: articleData.text || articleData.content || '',
    image_prompt: rawImagePrompt,
    image_url: imageUrl,
    image_caption: `Visual Summary & Infographic: ${topicData.topic}`
  }
};

const data = $input.item.json;
const rawText = data.article_text || '';

// Extract title from first markdown heading or fallback
let title = data.topic;
const headingMatch = rawText.match(/^#\s+(.+)$/m);
if (headingMatch && headingMatch[1]) {
  title = headingMatch[1].replace(/[*_#]/g, '').trim();
}

// Embedded Infographic Markdown
const infographicBlock = `\n\n---\n\n## 📊 Visual Summary & Key Takeaways\n\n![${title}](${data.image_url})\n*${data.image_caption}*\n\n---\n\n`;

// Inject infographic after the introductory paragraph
let finalContent = rawText;
if (finalContent.includes('\n\n')) {
  const parts = finalContent.split('\n\n');
  finalContent = parts[0] + '\n\n' + infographicBlock + parts.slice(1).join('\n\n');
} else {
  finalContent = infographicBlock + finalContent;
}

const excerpt = rawText.replace(/#+\s+/g, '').replace(/\n+/g, ' ').slice(0, 160).trim() + '...';

return {
  json: {
    request_id: `n8n-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    title: title,
    content: finalContent,
    excerpt: excerpt,
    category: (data.category || 'tech').toLowerCase(),
    tags: [data.category.toUpperCase(), 'Automated Draft', 'AI Infographic'],
    cover_image: data.image_url,
    cover_caption: data.image_caption,
    status: 'draft',
    template_type: 'standard',
    source_urls: [
      {
        title: `${title} - Research Source`,
        url: data.source_url || 'https://everygyan.com'
      }
    ]
  }
};

const item = $input.item.json;
const articleData = $('Format & Validate EveryGyan Article').item.json;

return {
  json: {
    name: articleData.title,
    content: articleData.content,
    article_id: item.data?.article_id || 'unknown',
    review_url: item.data?.review_url || 'https://everygyan.com/dashboard/articles'
  }
};
